import { useState } from "react";
import { Row } from "@/shared/ui/layout/Row";
import { Stack } from "@/shared/ui/layout/Stack";
import { Trophy } from "lucide-react";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";

// Vendored from `@/shared/lib/core/achievements` (unresolvable in this sandbox — the real module
// loads its registry via a Vite-only `import.meta.glob` over `src-tauri/data/achievements/*.json`,
// which the preview's esbuild pipeline can't resolve even as a value import). `isUnlocked` is the
// real pure helper, vendored verbatim; the achievement list below is representative sample data.
function isUnlocked(unlocked, id) {
  return Object.prototype.hasOwnProperty.call(unlocked, id);
}
const ACHIEVEMENTS = [
  { id: "first-project", title: "First project", description: "Created your first project." },
  { id: "fleet-of-five", title: "Fleet of five", description: "Ran five agents at once." },
  { id: "first-merge", title: "Shipped it", description: "Merged your first worker PR." },
  { id: "night-owl", title: "Night owl", description: "Ran a session after midnight." },
];
// Preview-only stand-in for `useAppStore((s) => s.achievements)` — the store is app-internal
// (unresolvable here). A couple unlocked so both states are visible.
const SAMPLE_UNLOCKED = { "first-project": Date.now() - 86400000, "fleet-of-five": Date.now() - 3600000 };

export function AchievementsCard() {
  const [achievements] = useState(SAMPLE_UNLOCKED);
  const unlockedCount = ACHIEVEMENTS.filter((a) => isUnlocked(achievements, a.id)).length;

  return (
    <Box style={{ maxWidth: 640 }}>
      <Row align="baseline" gap={10} style={{ marginBottom: 4 }}>
        <Text as="h2" mono size={16} style={{ margin: 0, color: "var(--fg)" }}>Achievements</Text>
        <Text mono size={11} tone="dim">
          {unlockedCount}/{ACHIEVEMENTS.length} unlocked
        </Text>
      </Row>
      <Text as="p" mono size="sm" tone="muted" style={{ margin: "0 0 18px" }}>
        Milestones you have earned. Each unlocks once and is kept across restarts.
      </Text>

      <Stack gap={10}>
        {ACHIEVEMENTS.map((a) => {
          const at = achievements[a.id];
          const unlocked = at != null;
          return (
            <Row key={a.id} gap={14} style={{
              padding: 12, borderRadius: 10,
              background: "var(--bg-panel)",
              border: "1px solid " + (unlocked ? "var(--accent)" : "var(--border-soft)"),
              opacity: unlocked ? 1 : 0.7,
            }}>
              <Box style={{
                flexShrink: 0, width: 48, height: 48, borderRadius: 10,
                display: "flex", alignItems: "center", justifyContent: "center",
                background: unlocked ? "var(--accent)" : "var(--bg-soft)",
                color: unlocked ? "var(--bg-canvas, var(--bg))" : "var(--fg-dim)",
                border: unlocked ? "none" : "1px solid var(--border)",
              }}>
                <Trophy size={22} />
              </Box>
              <Box style={{ flex: 1, minWidth: 0 }}>
                <Text as="div" mono size={13} style={{ color: "var(--fg)" }}>
                  {a.title}{!unlocked && <Text size={11} tone="dim"> · locked</Text>}
                </Text>
                <Text as="div" mono size={11} tone="muted" style={{ marginTop: 2 }}>
                  {a.description}
                </Text>
                {unlocked && (
                  <Text as="div" mono size={10} tone="accent" style={{ marginTop: 4 }}>
                    Unlocked {new Date(at).toLocaleDateString()}
                  </Text>
                )}
              </Box>
            </Row>
          );
        })}
      </Stack>
    </Box>
  );
}
